// ===== Binance への署名付きリクエストをまとめて組み立てる =====
// 1つのCodeノードで複数リクエストを作り、後段のCrypto/HTTPノードが1件ずつ処理する
const cfg = $('設定').first().json;

// --- 認証情報の存在チェック（n8n 2.0 以降 $env は既定でブロックされる）
let apiKey = '';
let apiSecret = '';
try {
  apiKey = ($env && $env.BINANCE_API_KEY) || '';
  apiSecret = ($env && $env.BINANCE_API_SECRET) || '';
} catch (e) {
  apiKey = '';
  apiSecret = '';
}
if (!apiKey || !apiSecret) {
  throw new Error(
    '環境変数 BINANCE_API_KEY / BINANCE_API_SECRET を参照できません。'
    + 'n8n 2.0 以降は N8N_BLOCK_ENV_ACCESS_IN_NODE の既定が true（ブロック）です。'
    + 'セルフホストなら N8N_BLOCK_ENV_ACCESS_IN_NODE=false を設定してください。',
  );
}

const now = Date.now();
const DAY = 86400000;
// 日境界(UTC 00:00)に揃える。揃えないと「30日前の当日早朝」の入出金だけが
// 取りこぼされ、シートに記録済みの値がリセットされて累計損益がずれる
const todayUtc0 = Math.floor(now / DAY) * DAY;
const FLOW_DAYS = 30;
const flowStart = todayUtc0 - FLOW_DAYS * DAY;

// スナップショットの照会期間は「30日未満」という制約がある。
// endTime を昨日の終わりに固定すると、実行時刻に関係なく常に 29日 − 1ms で安全
const snapStart = todayUtc0 - 29 * DAY;
const snapEnd = todayUtc0 - 1;

const q = (o) => Object.entries(o)
  .filter(([, v]) => v !== undefined && v !== null && v !== '')
  .map(([k, v]) => `${k}=${encodeURIComponent(v)}`)
  .join('&');

// recvWindow は最大 60000。15リクエストを逐次実行するため、
// timestamp を組み立て時に1回だけ計算する構成では 5000 だと後半が -1021 で落ちる
const RECV = 60000;

const reqs = [];

// --- 日次資産スナップショット（weight: IP 2400 / limit最大30 / 照会期間は30日未満・直近1ヶ月のみ）
reqs.push({
  kind: 'snapshot',
  endpoint: '/sapi/v1/accountSnapshot',
  query: q({ type: 'SPOT', startTime: snapStart, endTime: snapEnd, limit: 30, recvWindow: RECV, timestamp: now }),
});

// --- 暗号資産の入出金（weight: 入金 IP 1 / 出金 UID 18000・毎秒10回まで。どちらも照会期間は90日未満）
reqs.push({
  kind: 'deposit',
  endpoint: '/sapi/v1/capital/deposit/hisrec',
  query: q({ startTime: flowStart, endTime: now, limit: 1000, recvWindow: RECV, timestamp: now }),
});
reqs.push({
  kind: 'withdraw',
  endpoint: '/sapi/v1/capital/withdraw/history',
  query: q({ startTime: flowStart, endTime: now, limit: 1000, recvWindow: RECV, timestamp: now }),
});

// --- 法定通貨(JPY)の入出金
// /sapi/v1/fiat/orders は重い。現行のAPIリファレンスは UID 45000、
// 変更履歴(2022-05-31)は UID 90000 と記載があり食い違っている。
// UID制限はエンドポイントごとに独立して毎分180000なので、入金・出金の2回で90000〜180000を消費する。
// 1日1回なら問題ないが、同じ1分内に手動で再実行すると 429 になりうる（後段で専用メッセージを出す）
if (cfg.trackFiat) {
  for (const t of ['0', '1']) {
    reqs.push({
      kind: t === '0' ? 'fiatDeposit' : 'fiatWithdraw',
      endpoint: '/sapi/v1/fiat/orders',
      query: q({ transactionType: t, beginTime: flowStart, endTime: now, rows: 500, recvWindow: RECV, timestamp: now }),
    });
  }
  // 法定通貨で直接売買した分（weight: IP 1 と軽い。paymentMethod は transactionType=0 のときだけ返る）
  for (const t of ['0', '1']) {
    reqs.push({
      kind: t === '0' ? 'fiatBuy' : 'fiatSell',
      endpoint: '/sapi/v1/fiat/payments',
      query: q({ transactionType: t, beginTime: flowStart, endTime: now, rows: 500, recvWindow: RECV, timestamp: now }),
    });
  }
}

// --- ウォレット間の振替（weight: IP 1 / size最大100 / 照会は直近6ヶ月まで）
if (cfg.trackTransfers) {
  const types = [
    'MAIN_FUNDING', 'FUNDING_MAIN',
    'MAIN_UMFUTURE', 'UMFUTURE_MAIN',
    'MAIN_CMFUTURE', 'CMFUTURE_MAIN',
    'MAIN_MARGIN', 'MARGIN_MAIN',
  ];
  for (const t of types) {
    reqs.push({
      kind: `transfer:${t}`,
      endpoint: '/sapi/v1/asset/transfer',
      query: q({ type: t, startTime: flowStart, endTime: now, size: 100, recvWindow: RECV, timestamp: now }),
    });
  }
}

return reqs.map((r) => ({ json: { baseUrl: 'https://api.binance.com', flowStart, ...r } }));

// ===== 複数レスポンスを種類別に仕分けし、入出金を正規化する =====
const cfg = $('設定').first().json;
const reqs = $('リクエストを組み立て').all().map((i) => i.json);
const items = $input.all();

const idxOf = (it, i) => {
  const p = it.pairedItem;
  if (typeof p === 'number') return p;
  if (p && typeof p.item === 'number') return p.item;
  if (Array.isArray(p) && p.length && typeof p[0].item === 'number') return p[0].item;
  return i;
};

// "2019-10-12 11:12:02" (UTC) / ミリ秒数値 のどちらにも対応
const toMs = (v) => {
  if (v === undefined || v === null || v === '') return 0;
  if (typeof v === 'number') return v;
  if (/^\d+$/.test(String(v))) return Number(v);
  const t = Date.parse(String(v).replace(' ', 'T') + 'Z');
  return Number.isFinite(t) ? t : 0;
};

let snapshots = [];
const flows = [];          // { time, coin, amount(符号付き), label }
const errors = [];         // Slackに警告として出す取得エラー
const review = [];         // 判断が必要なもの
const skippedWallets = []; // 未開設のウォレット（毎日出るノイズなので警告にしない）

// 認証・時刻ずれ・レート制限は種類を問わず必ず報告する
const ALWAYS_REPORT = new Set([-1021, -1022, -1002, -1003, -2014, -2015]);

items.forEach((it, i) => {
  const req = reqs[idxOf(it, i)] || reqs[i] || {};
  const kind = req.kind || 'unknown';
  const res = it.json || {};
  const body = res.body !== undefined ? res.body : res;
  const status = res.statusCode;
  const code = body && body.code !== undefined ? Number(body.code) : NaN;

  const isError = (status && status >= 400)
    || (body && body.code && body.code !== 200 && body.code !== '000000' && body.msg);

  if (isError) {
    // レート制限は原因が分かりにくいので専用メッセージにする
    if (status === 429 || code === -1003) {
      errors.push({
        kind,
        status: status || code,
        msg: 'Binanceのレート制限に達しました（/sapi/v1/fiat/orders は1回あたりUID weight 45000〜90000、'
          + 'このエンドポイント単独の上限は毎分180000です。同じ1分内に再実行しないでください）',
      });
      return;
    }
    // 未開設のマージン/先物ウォレットは毎回エラーになるため警告から除外する
    if (kind.startsWith('transfer:') && !ALWAYS_REPORT.has(code)) {
      skippedWallets.push(kind.slice('transfer:'.length));
      return;
    }
    errors.push({ kind, status: status || body.code, msg: (body && (body.msg || body.message)) || '' });
    return;
  }

  if (kind === 'snapshot') {
    snapshots = (body && body.snapshotVos) || [];
    return;
  }

  if (kind === 'deposit') {
    // status 0=処理中 1=成功 2=拒否 6=着金済(出金不可) 7=誤入金 8=ユーザー確認待ち
    for (const r of (Array.isArray(body) ? body : [])) {
      if (![1, 6].includes(Number(r.status))) continue;
      // travelRuleStatus 1 = トラベルルールの情報提出待ち。残高に反映されていない可能性がある
      if (Number(r.travelRuleStatus) === 1) {
        review.push(
          `${new Date(toMs(r.insertTime)).toISOString().slice(0, 10)} の ${r.coin} 入金 ${r.amount} は`
          + 'トラベルルールの情報提出待ちです。残高に反映されていない場合は入出金から除外してください',
        );
      }
      flows.push({ time: toMs(r.insertTime), coin: r.coin, amount: Number(r.amount), label: '入金' });
    }
    return;
  }

  if (kind === 'withdraw') {
    for (const r of (Array.isArray(body) ? body : [])) {
      // 0=メール送信 2=承認待ち 4=処理中 6=完了（いずれも残高は引かれている）
      if (![0, 2, 4, 6].includes(Number(r.status))) continue;
      flows.push({ time: toMs(r.applyTime || r.completeTime), coin: r.coin, amount: -Number(r.amount), label: '出金' });
    }
    return;
  }

  // 法定通貨の入出金。PayPayマネーからの入金はここに method="PayPay money" で出る（実機確認済み）
  //   例: indicatedAmount 15000 − totalFee 110 = amount 14890 がウォレットに入る
  if (kind === 'fiatDeposit' || kind === 'fiatWithdraw') {
    const isDeposit = kind === 'fiatDeposit';
    for (const r of ((body && body.data) || [])) {
      if (!['Successful', 'Finished'].includes(String(r.status))) continue;
      const net = Number(r.amount);                 // 入金: 実際にウォレットへ入る額
      const gross = Number(r.indicatedAmount);      // 出金: ウォレットから引かれる額（手数料込み）
      let amt;
      if (isDeposit) {
        // 既定は net。手数料を損失として記録したい場合は 設定 で gross に切り替える
        amt = (cfg.countDepositFeeAsLoss && Number.isFinite(gross)) ? gross : net;
      } else {
        amt = -(Number.isFinite(gross) ? gross : net);
      }
      flows.push({
        time: toMs(r.createTime),
        coin: r.fiatCurrency,
        amount: amt,
        label: `法定通貨${isDeposit ? '入金' : '出金'}${r.method ? `(${r.method})` : ''}`,
      });
    }
    return;
  }

  // 法定通貨での購入。PayPay運用では「入金→残高で購入」の2段階になり全件 Cash Balance になる（実機確認済み）
  // ＝ ここは通常すべて除外される。将来カード等の外部決済で直接買った場合の取りこぼし防止用に残してある
  if (kind === 'fiatBuy') {
    for (const r of ((body && body.data) || [])) {
      if (!['Completed', 'Successful', 'Finished'].includes(String(r.status))) continue;
      const method = String(r.paymentMethod || '');
      // "Cash Balance" はウォレット内の残高で買っているので資金の出入りではない
      if (/cash\s*balance/i.test(method)) continue;
      const jpy = Number(r.sourceAmount) - (Number(r.totalFee) || 0);
      flows.push({
        time: toMs(r.createTime),
        coin: r.fiatCurrency,
        amount: jpy,
        label: `法定通貨購入${method ? `(${method})` : ''}`,
      });
    }
    return;
  }

  if (kind === 'fiatSell') {
    for (const r of ((body && body.data) || [])) {
      if (!['Completed', 'Successful', 'Finished'].includes(String(r.status))) continue;
      const jpy = Number(r.obtainAmount) || Number(r.sourceAmount) || 0;
      review.push(`法定通貨売却 ${new Date(toMs(r.createTime)).toISOString().slice(0, 10)} ${jpy}${r.fiatCurrency || ''}`);
      if (!cfg.countFiatSell) continue;
      flows.push({
        time: toMs(r.createTime),
        coin: r.fiatCurrency,
        amount: -jpy,
        label: '法定通貨売却',
      });
    }
    return;
  }

  if (kind.startsWith('transfer:')) {
    const type = kind.slice('transfer:'.length);
    const sign = type.startsWith('MAIN_') ? -1 : 1;   // MAIN=現物ウォレット
    for (const r of ((body && body.rows) || [])) {
      if (String(r.status) !== 'CONFIRMED') continue;
      flows.push({
        time: toMs(r.timestamp),
        coin: r.asset,
        amount: sign * Number(r.amount),
        label: `ウォレット振替(${type})`,
      });
    }
  }
});

const clean = flows.filter((f) => f.time && f.coin && Number.isFinite(f.amount) && f.amount !== 0);

// --- 二重計上の検出 -------------------------------------------------
// 法定通貨がFundingに着金 → Spotへ振替、という経路だと
// 「法定通貨入金」と「FUNDING_MAIN振替」の両方が流入として加算されてしまう。
// 同じ日・同じ通貨・ほぼ同額の組み合わせが見つかったら要確認に出す。
const dayOf = (ms) => new Date(ms).toISOString().slice(0, 10);
for (const dep of clean) {
  if (!/^法定通貨入金/.test(dep.label) || dep.amount <= 0) continue;
  const hit = clean.find((t) => t.label === 'ウォレット振替(FUNDING_MAIN)'
    && t.coin === dep.coin
    && dayOf(t.time) === dayOf(dep.time)
    && Math.abs(t.amount - dep.amount) / Math.max(Math.abs(dep.amount), 1) <= 0.05);
  if (hit) {
    review.push(
      `${dayOf(dep.time)} の ${dep.coin} 入金が「法定通貨入金」と「FUNDING_MAIN振替」で二重計上されている可能性があります`
      + `（各 ${Math.round(dep.amount).toLocaleString('ja-JP')}）。実際の着金先ウォレットを確認してください`,
    );
  }
}

return [{
  json: {
    snapshots,
    flows: clean,
    errors,
    review,
    skippedWallets: [...new Set(skippedWallets)],
    flowStart: reqs.length ? reqs[0].flowStart : 0,
  },
}];

// ===== 履歴・スナップショット・入出金をマージして推移を再計算 =====
const cfg = $('設定').first().json;
const src = $('レスポンスを仕分け').first().json;

const DAY = 86400000;
const utcDate = (ms) => new Date(Number(ms)).toISOString().slice(0, 10);
const num = (v) => {
  const n = Number(String(v ?? '').replace(/[,¥\s]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const isBlank = (v) => v === undefined || v === null || String(v).trim() === '';

// 処理を中止して理由をSlackに出すための共通の戻り値
const abort = (reason) => ([{
  json: {
    fatal: reason,
    history: [], newRows: [], composition: [], compositionDate: null,
    rateSource: '', btcJpy: 0, latestDate: null,
    errors: src.errors || [], review: src.review || [],
    skippedWallets: src.skippedWallets || [],
    anomalies: [], incomplete: [], skippedDates: [], unconverted: [],
  },
}]);

// ---------- 1. 価格テーブル ----------
const px = {};
try {
  const body = $('価格一覧を取得').first().json.body || [];
  for (const p of body) px[p.symbol] = Number(p.price);
} catch (e) { /* noop */ }

// 為替レート（日次）: { "2026-09-18": { JPY: 152.34 }, ... } 営業日のみ
let fxByDate = {};
try {
  const fx = $('為替レート（日次）').first().json;
  fxByDate = (fx && fx.rates) || {};
} catch (e) { fxByDate = {}; }
const fxDates = Object.keys(fxByDate).sort();

// 為替APIが一時的に落ちてもレポートを止めないよう、最後に取れた値を保持しておく
const sd = (typeof $getWorkflowStaticData === 'function') ? $getWorkflowStaticData('global') : {};
const fxNotes = [];
let usdJpyFx = fxDates.length ? num(fxByDate[fxDates[fxDates.length - 1]].JPY) : 0;
if (usdJpyFx > 0) {
  sd.usdJpy = usdJpyFx;
  sd.usdJpyDate = fxDates[fxDates.length - 1];
} else if (num(sd.usdJpy) > 0) {
  usdJpyFx = num(sd.usdJpy);
  fxNotes.push(`為替レートを取得できなかったため前回値 ${usdJpyFx.toFixed(2)} (${sd.usdJpyDate || '日付不明'}) を使用しました`);
}

// 土日祝は前営業日のレートを使う
const usdJpyAt = (d) => {
  let v = 0;
  for (const k of fxDates) {
    if (k <= d) v = num(fxByDate[k].JPY); else break;
  }
  return v || usdJpyFx;
};

const usdtJpy = (px.BTCJPY && px.BTCUSDT) ? px.BTCJPY / px.BTCUSDT : (px.USDTJPY || usdJpyFx);
const btcJpyNow = px.BTCJPY || (px.BTCUSDT ? px.BTCUSDT * usdtJpy : 0);

// 円換算レートが取れないまま書き込むと総資産0円・巨額の偽損失がシートに残るため中止する
if (!(btcJpyNow > 0)) {
  return abort(
    'BTC/JPY の評価レートを取得できませんでした'
    + `（Binance価格一覧: ${px.BTCUSDT ? 'OK' : '失敗'} / 為替: ${usdJpyFx ? 'OK' : '失敗'}）。`
    + 'シートに誤った値を書き込まないよう、記録と集計を中止しました。',
  );
}

// ---------- 1-b. 日ごとのBTC/JPYレート ----------
// 初回のバックフィルで過去30日ぶんを「今日のレート」で評価すると、
// その期間の損益が数量変化しか反映しなくなるため、日足終値から日別レートを作る
const dailyBtcJpy = {};
try {
  const kl = $('日次BTC価格を取得').first().json.body || [];
  for (const k of kl) {
    if (!Array.isArray(k) || k.length < 5) continue;
    const d = utcDate(k[0]);                 // 日足のopenTime = その日の00:00 UTC
    const closeUsdt = Number(k[4]);          // 終値 = その日の23:59:59 UTC 時点
    const fx = usdJpyAt(d);
    if (closeUsdt > 0 && fx > 0) dailyBtcJpy[d] = closeUsdt * fx;
  }
} catch (e) { /* noop: btcJpyNow にフォールバック */ }
const rateAt = (d) => dailyBtcJpy[d] || btcJpyNow;

const rateSource = px.BTCJPY
  ? 'BTCJPY'
  : `BTCUSDT×USDJPY(${usdJpyFx.toFixed(2)})${Object.keys(dailyBtcJpy).length ? '・過去日は日足終値' : ''}`;

const STABLE = ['USDT', 'USDC', 'FDUSD', 'BUSD', 'DAI', 'TUSD'];
// その日のBTC/JPYレートを基準に、現在のコイン/BTC比率で換算する
const toJpy = (coin, amt, btcRate) => {
  const rate = btcRate || btcJpyNow;
  if (!amt || !coin) return 0;
  if (coin === 'JPY') return amt;
  if (coin === 'BTC') return amt * rate;
  if (px[`${coin}BTC`]) return amt * px[`${coin}BTC`] * rate;
  if (px[`${coin}USDT`] && px.BTCUSDT) return amt * (px[`${coin}USDT`] / px.BTCUSDT) * rate;
  if (STABLE.includes(coin) && px.BTCUSDT) return amt * (1 / px.BTCUSDT) * rate;
  if (px[`${coin}JPY`]) return amt * px[`${coin}JPY`];
  return NaN;   // 換算不能 → 後段で警告
};

// ---------- 2. 既存履歴（スプレッドシート） ----------
// シートの見出し（1行目）。ここを書き換えれば列名を変更できる
const COL = {
  date: '日付',
  total_btc: '総資産(BTC)',
  btc_price_jpy: 'BTC価格(円)',   // 書き込まない（旧シートに残っていれば読むだけ）
  total_jpy: '総資産(円)',
  net_flow_jpy: '入出金(円)',
  flow_note: '入出金メモ',
  daily_pnl_jpy: '日次損益(円)',
  daily_pnl_pct: '日次損益率(%)',
  cumulative_pnl_jpy: '累計損益(円)',
  net_flow_override_jpy: '入出金の手動補正(円)',
};
// 日本語見出しを優先しつつ、旧・英語見出しのシートもそのまま読めるようにする
const col = (r, key) => (r[COL[key]] !== undefined ? r[COL[key]] : r[key]);

// 日付セルがテキストでなく日付型になっていると "2026/09/19" 等で返り、
// キーが一致せず行が増殖する。読み取り側で正規化して吸収する
const SHEET_EPOCH = Date.UTC(1899, 11, 30);
const dateWarn = new Set();
const normDate = (v) => {
  if (v === undefined || v === null) return '';
  if (v instanceof Date) return v.toISOString().slice(0, 10);
  if (typeof v === 'number') {
    if (v > 20000 && v < 80000) { dateWarn.add('シリアル値'); return new Date(SHEET_EPOCH + Math.round(v) * DAY).toISOString().slice(0, 10); }
    if (v > 1e12) return new Date(v).toISOString().slice(0, 10);
    return '';
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
  if (m) { if (s[4] !== '-') dateWarn.add(s.slice(0, 10)); return `${m[1]}-${String(m[2]).padStart(2, '0')}-${String(m[3]).padStart(2, '0')}`; }
  m = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);
  if (m) { dateWarn.add(s.slice(0, 10)); return `${m[3]}-${String(m[1]).padStart(2, '0')}-${String(m[2]).padStart(2, '0')}`; }
  m = s.match(/^(\d{4})年(\d{1,2})月(\d{1,2})日/);
  if (m) { dateWarn.add(s.slice(0, 12)); return `${m[1]}-${String(m[2]).padStart(2, '0')}-${String(m[3]).padStart(2, '0')}`; }
  const t = Date.parse(s);
  if (Number.isFinite(t)) { dateWarn.add(s.slice(0, 12)); return new Date(t).toISOString().slice(0, 10); }
  return '';
};

const rawExisting = $('履歴を読み込み').all().map((i) => i.json);
// 読み込みに失敗したまま進むと、履歴が直近30日だけで再構築され
// 累計損益が0から振り直された値でシートを上書きしてしまう
const readErrRow = rawExisting.find((r) => r && r.error && isBlank(col(r, 'date')));
if (readErrRow) {
  const m = typeof readErrRow.error === 'string' ? readErrRow.error : (readErrRow.error.message || JSON.stringify(readErrRow.error));
  return abort(`スプレッドシートの読み込みに失敗しました（${m}）。累計損益が壊れるため、記録と集計を中止しました。`);
}

const existing = rawExisting.filter((r) => r && !isBlank(col(r, 'date')) && normDate(col(r, 'date')));

const map = new Map();
for (const r of existing) {
  const d = normDate(col(r, 'date'));
  const totalBtc = num(col(r, 'total_btc'));
  const totalJpy = num(col(r, 'total_jpy'));
  // BTC価格(円)はシートに書き込まないので 総資産(円) ÷ 総資産(BTC) で復元する
  const storedPrice = col(r, 'btc_price_jpy');
  map.set(d, {
    date: d,
    total_btc: totalBtc,
    btc_price_jpy: isBlank(storedPrice) ? (totalBtc ? totalJpy / totalBtc : 0) : num(storedPrice),
    total_jpy: totalJpy,
    net_flow_jpy: num(col(r, 'net_flow_jpy')),
    flow_note: col(r, 'flow_note') || '',
    // 自動検出を上書きしたいときだけ手入力する列（通常は空のまま）
    _override: isBlank(col(r, 'net_flow_override_jpy')) ? null : num(col(r, 'net_flow_override_jpy')),
  });
}

// ---------- 3-0. 不完全なスナップショットを検出 ----------
// Binanceが balances の一部を欠落させたまま totalAssetOfBtc を返すことがある。
// 前日にあった資産が丸ごと消え、かつそれを戻すと前日の総額が再現できる日は
// 「実際に減ったのではなく取得漏れ」と判断して集計から除外する。
const snapsSorted = (src.snapshots || [])
  .filter((s) => s && s.updateTime && s.data)
  .slice()
  .sort((a, b) => Number(a.updateTime) - Number(b.updateTime));

const balOf = (s) => {
  const m = new Map();
  for (const b of (s.data.balances || [])) {
    const amt = Number(b.free || 0) + Number(b.locked || 0);
    if (amt > 0) m.set(b.asset, amt);
  }
  return m;
};

// コイン数量 → BTC建て評価
const toBtc = (coin, amt) => {
  if (!amt || !coin) return NaN;
  if (coin === 'BTC') return amt;
  if (px[`${coin}BTC`]) return amt * px[`${coin}BTC`];
  if (px[`${coin}USDT`] && px.BTCUSDT) return amt * (px[`${coin}USDT`] / px.BTCUSDT);
  if (STABLE.includes(coin) && px.BTCUSDT) return amt / px.BTCUSDT;
  if (coin === 'JPY') return btcJpyNow ? amt / btcJpyNow : NaN;
  if (px[`${coin}JPY`] && btcJpyNow) return (amt * px[`${coin}JPY`]) / btcJpyNow;
  return NaN;
};

// その日に出金・振替が検出されたコイン（正当な減少かどうかの判定に使う）
const outflowOf = new Map();
for (const f of (src.flows || [])) {
  if (!(Number(f.amount) < 0)) continue;
  const d = utcDate(f.time);
  if (!outflowOf.has(d)) outflowOf.set(d, new Set());
  outflowOf.get(d).add(f.coin);
}

const badDates = new Map();   // date -> 欠損スナップショットが報告した totalAssetOfBtc
const incomplete = [];
for (let i = 1; i < snapsSorted.length; i++) {
  const p = snapsSorted[i - 1];
  const s = snapsSorted[i];
  const d = utcDate(s.updateTime);
  const pb = balOf(p);
  const sb = balOf(s);
  const missing = [...pb.keys()].filter((a) => !sb.has(a));
  if (!missing.length) continue;
  // 出金・振替が検出されていれば正当な減少
  const out = outflowOf.get(d) || new Set();
  if (missing.some((a) => out.has(a))) continue;

  const pTot = Number(p.data.totalAssetOfBtc);
  const sTot = Number(s.data.totalAssetOfBtc);
  if (!(pTot > 0) || !Number.isFinite(sTot) || sTot >= pTot) continue;

  let missBtc = 0;
  let evaluable = true;
  for (const a of missing) {
    const v = toBtc(a, pb.get(a));
    if (!Number.isFinite(v)) { evaluable = false; break; }
    missBtc += v;
  }
  if (!evaluable) continue;

  // 消えた資産を戻すと前日の総額とほぼ一致する = 資産は動いていない
  // （売却・両替なら総額は保たれるのでここには該当しない）
  if (Math.abs((sTot + missBtc) - pTot) / pTot <= 0.10) {
    badDates.set(d, sTot);
    incomplete.push(`${d} のスナップショットが不完全なため集計から除外しました（${missing.join(', ')} が欠落。Binance側の取得漏れ）`);
  }
}

// 既にシートへ書き込まれた欠損値の行も集計から外す（値が一致する場合のみ）
for (const [d, badTot] of badDates) {
  const row = map.get(d);
  if (!row) continue;
  const ref = Math.max(Math.abs(badTot), 1e-12);
  if (Math.abs(row.total_btc - badTot) / ref <= 0.02) {
    map.delete(d);
    incomplete.push(`${d} の記録済みの行は欠損値のため無効化しました（シートの該当行は手動で削除してください）`);
  }
}

// ---------- 3-1. 最新の資産構成（円グラフ用） ----------
const lastGood = [...snapsSorted].reverse().find((s) => !badDates.has(utcDate(s.updateTime)));
const composition = [];
let compositionDate = null;
if (lastGood) {
  compositionDate = utcDate(lastGood.updateTime);
  for (const [coin, amt] of balOf(lastGood)) {
    const b = toBtc(coin, amt);
    const jpy = Number.isFinite(b) ? b * btcJpyNow : NaN;
    if (Number.isFinite(jpy) && jpy > 0) composition.push({ coin, amount: amt, jpy: Math.round(jpy) });
  }
  composition.sort((a, b) => b.jpy - a.jpy);
}

// ---------- 3. スナップショットを反映 ----------
const freshDates = [];
for (const s of (src.snapshots || [])) {
  if (!s || !s.updateTime || !s.data) continue;
  const d = utcDate(s.updateTime);
  if (badDates.has(d)) continue;
  const btc = num(s.data.totalAssetOfBtc);
  const prev = map.get(d) || {};
  // 一度記録した日の評価レートは維持する。未記録の日はその日の日足レートを使う
  const price = prev.btc_price_jpy || rateAt(d);
  map.set(d, {
    ...prev,
    date: d,
    total_btc: btc,
    btc_price_jpy: price,
    total_jpy: btc * price,
    net_flow_jpy: prev.net_flow_jpy || 0,
    flow_note: prev.flow_note || '',
    _override: prev._override ?? null,
  });
  freshDates.push(d);
}

// ---------- 4. 入出金を日別に集計（取得できた期間のみ再計算） ----------
const flowFrom = src.flowStart ? utcDate(src.flowStart) : null;
const unconverted = [];
if (flowFrom) {
  for (const [d, row] of map) {
    if (d >= flowFrom) { row.net_flow_jpy = 0; row.flow_note = ''; }
  }
  const bucket = new Map();
  for (const f of (src.flows || [])) {
    const d = utcDate(f.time);
    if (d < flowFrom) continue;
    if (!bucket.has(d)) bucket.set(d, { jpy: 0, notes: new Map() });
    const b = bucket.get(d);
    const row = map.get(d);
    const jpy = toJpy(f.coin, f.amount, row ? row.btc_price_jpy : rateAt(d));
    if (!Number.isFinite(jpy)) { unconverted.push(`${d} ${f.coin}`); continue; }
    b.jpy += jpy;
    const short = f.label.replace(/^ウォレット振替\(.+\)$/, 'ウォレット振替');
    b.notes.set(short, (b.notes.get(short) || 0) + 1);
  }
  for (const [d, b] of bucket) {
    const row = map.get(d);
    if (!row) continue;
    row.net_flow_jpy = Math.round(b.jpy);
    row.flow_note = [...b.notes.entries()].map(([k, v]) => `${k}${v}件`).join(' / ');
  }
}

// ---------- 5. 日次損益・累計を再計算 ----------
const history = [...map.values()].sort((a, b) => (a.date < b.date ? -1 : 1));
let cum = 0;
for (let i = 0; i < history.length; i++) {
  const r = history[i];
  const p = history[i - 1];
  const flow = r._override !== null && r._override !== undefined ? r._override : r.net_flow_jpy;
  // 収益 = 総資産の増減 − 入出金
  const diff = p ? r.total_jpy - p.total_jpy - flow : 0;
  const base = p ? p.total_jpy + flow : 0;
  cum += diff;
  r.effective_flow_jpy = Math.round(flow);
  r.total_btc = Number(r.total_btc.toFixed(8));
  r.btc_price_jpy = Math.round(r.btc_price_jpy);
  r.total_jpy = Math.round(r.total_jpy);
  r.net_flow_jpy = Math.round(r.net_flow_jpy);
  r.daily_pnl_jpy = Math.round(diff);
  r.daily_pnl_pct = base ? Number(((diff / base) * 100).toFixed(3)) : 0;
  r.cumulative_pnl_jpy = Math.round(cum);
}

// ---------- 6. 書き込み対象（手入力列は書き戻さない） ----------
const from = freshDates.length ? freshDates.slice().sort()[0] : null;
const writable = (r) => ({
  [COL.date]: r.date,
  [COL.total_btc]: r.total_btc,
  [COL.total_jpy]: r.total_jpy,
  [COL.net_flow_jpy]: r.net_flow_jpy,
  [COL.flow_note]: r.flow_note,
  [COL.daily_pnl_jpy]: r.daily_pnl_jpy,
  [COL.daily_pnl_pct]: r.daily_pnl_pct,
  [COL.cumulative_pnl_jpy]: r.cumulative_pnl_jpy,
});
const newRows = from ? history.filter((r) => r.date >= from).map(writable) : [];

// ---------- 7. 入出金の取りこぼし検知 ----------
// 入出金が検出されていないのに総資産が大きく動いた日を洗い出す。
// 暗号資産は15%程度なら普通に動くので、率と実額の両方をしきい値にする
const anomalyPct = Number(cfg.anomalyPct) || 20;
const anomalyMinJpy = Number(cfg.anomalyMinJpy) || 0;
const anomalies = [];
for (let i = 1; i < history.length; i++) {
  const r = history[i];
  const p = history[i - 1];
  if (flowFrom && r.date < flowFrom) continue;
  if (r.effective_flow_jpy) continue;
  if (!p.total_jpy) continue;
  if (Math.abs(r.daily_pnl_jpy) < anomalyMinJpy) continue;
  if (Math.abs(r.daily_pnl_jpy / p.total_jpy) * 100 >= anomalyPct) {
    anomalies.push(`${r.date} の変動 ${r.daily_pnl_jpy >= 0 ? '+' : ''}${r.daily_pnl_jpy.toLocaleString('ja-JP')}円 (${r.daily_pnl_pct}%) に対応する入出金が未検出`);
  }
}

const review = [...(src.review || []), ...fxNotes];
if (dateWarn.size) {
  review.push(`シートの「${COL.date}」列が日付型として読まれています（例: ${[...dateWarn][0]}）。書式を「書式なしテキスト」にすると行の重複を防げます`);
}

return [{
  json: {
    fatal: null,
    history,
    newRows,
    rateSource,
    btcJpy: Math.round(btcJpyNow),
    errors: src.errors || [],
    review,
    skippedWallets: src.skippedWallets || [],
    anomalies,
    incomplete,
    skippedDates: [...badDates.keys()],
    composition,
    compositionDate,
    unconverted: [...new Set(unconverted)],
    latestDate: history.length ? history[history.length - 1].date : null,
  },
}];

// ===== Slack Block Kit メッセージ生成（JPY建て） =====
const cfg = $('設定').first().json;
const src = $input.first().json;

// 投稿先チャンネル（設定ノードで管理し、送信ノードには $json.channel として渡す）
const channel = String(cfg.slackChannel || '').trim();
if (!channel) {
  throw new Error('設定ノードの slackChannel が空です。投稿先チャンネルのID（C から始まる文字列）を指定してください。');
}
const history = src.history || [];

// data_visualization ブロックを使うか（false ならテキストのグラフにフォールバック）
const useChartBlocks = cfg.useChartBlocks !== false;
// グラフに載せる日数（data_visualization の上限は 20 点）
const chartDays = Math.min(20, Math.max(2, Number(cfg.chartDays) || 14));

const yen = (n) => `${Math.round(Math.abs(n)).toLocaleString('ja-JP')} 円`;
const signedYen = (n) => `${n >= 0 ? '+' : '-'}${yen(n)}`;
const man = (n) => {
  const v = Math.abs(n) / 10000;
  return `${n >= 0 ? '+' : '-'}${v.toLocaleString('ja-JP', { minimumFractionDigits: 1, maximumFractionDigits: 1 })}万`;
};
const pct = (n) => `${n >= 0 ? '+' : '-'}${Math.abs(n).toFixed(2)}%`;
const emo = (n) => (n > 0 ? '🟢' : n < 0 ? '🔴' : '⚪️');

const spark = (arr) => {
  if (!arr.length) return '';
  const chars = '▁▂▃▄▅▆▇█';
  const mn = Math.min(...arr);
  const mx = Math.max(...arr);
  const rng = (mx - mn) || 1;
  return arr.map((v) => chars[Math.min(7, Math.floor(((v - mn) / rng) * 7.999))]).join('');
};

// ---- 中止された場合（レート取得失敗・シート読み込み失敗など）
if (src.fatal) {
  const detail = (src.errors || []).map((e) => `${e.kind}: ${e.msg || e.status}`).slice(0, 5);
  return [{
    json: {
      channel,
      blocks: [
        { type: 'section', text: { type: 'mrkdwn', text: `🛑 *Binance 収益レポートを中止しました*\n${src.fatal}` } },
        ...(detail.length ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: detail.map((d) => `• ${d}`).join('\n') }] }] : []),
        { type: 'context', elements: [{ type: 'mrkdwn', text: 'シートへの書き込みは行っていません。次回の実行で自動的に復旧します。' }] },
      ],
      fallbackText: `Binance 収益レポート: 中止（${src.fatal}）`,
    },
  }];
}

const latest = history[history.length - 1];
if (!latest) {
  const why = (src.errors || []).map((e) => `${e.kind}: ${e.msg || e.status}`).join(' / ') || 'レスポンスが空でした';
  return [{
    json: {
      channel,
      blocks: [{ type: 'section', text: { type: 'mrkdwn', text: `⚠️ Binance のスナップショットを取得できませんでした。\n\`${why}\`` } }],
      fallbackText: 'Binance 収益レポート: データ取得に失敗しました',
    },
  }];
}

const sumLast = (n) => history.slice(-n).reduce((a, b) => a + b.daily_pnl_jpy, 0);
const n7 = Math.min(7, history.length);
const n30 = Math.min(30, history.length);
const day1 = latest.daily_pnl_jpy;
const day7 = sumLast(n7);
const day30 = sumLast(n30);
const cumTotal = latest.cumulative_pnl_jpy;
const firstDate = history[0].date;

const principal = history[0].total_jpy + history.slice(1).reduce((a, b) => a + (b.effective_flow_jpy || 0), 0);
const totalPct = principal ? (cumTotal / principal) * 100 : 0;

const peak = history.reduce((m, r) => (r.total_jpy > m.total_jpy ? r : m), history[0]);
const drawdown = peak.total_jpy ? ((latest.total_jpy - peak.total_jpy) / peak.total_jpy) * 100 : 0;

const nowRate = src.btcJpy || latest.btc_price_jpy;
const rateNote = nowRate === latest.btc_price_jpy
  ? `評価レート 1BTC = ${yen(latest.btc_price_jpy)} (${src.rateSource})`
  : `${latest.date}の評価レート 1BTC = ${yen(latest.btc_price_jpy)} ・ 現在 ${yen(nowRate)} (${src.rateSource})`;

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: '📊 Binance 現物 収益レポート', emoji: true } },
  {
    type: 'context',
    elements: [{ type: 'mrkdwn', text: `対象日 *${latest.date}* (UTC基準) ・ 記録 ${history.length}日分 ・ ${firstDate} 〜` }],
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*総資産*\n*${yen(latest.total_jpy)}*  ( ${latest.total_btc.toFixed(8)} BTC )\n`
        + `前日比 ${emo(day1)} ${signedYen(day1)} ( ${pct(latest.daily_pnl_pct)} )`,
    },
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*直近${n7}日*\n${emo(day7)} ${signedYen(day7)}` },
      { type: 'mrkdwn', text: `*直近${n30}日*\n${emo(day30)} ${signedYen(day30)}` },
      { type: 'mrkdwn', text: `*累計損益*\n${emo(cumTotal)} ${signedYen(cumTotal)}` },
      { type: 'mrkdwn', text: `*累計リターン*\n${emo(totalPct)} ${pct(totalPct)}` },
    ],
  },
];

// 入出金が検出された日は明示する（収益から除外済み）
const flowDays = history.slice(-7).filter((r) => r.effective_flow_jpy);
if (flowDays.length) {
  blocks.push({
    type: 'context',
    elements: [{
      type: 'mrkdwn',
      text: `⇄ 直近7日の入出金（収益から除外済み）: `
        + flowDays.map((r) => `${r.date.slice(5)} ${signedYen(r.effective_flow_jpy)}${r.flow_note ? `（${r.flow_note}）` : ''}`).join(' ・ '),
    }],
  });
}

blocks.push({
  type: 'context',
  elements: [{
    type: 'mrkdwn',
    text: `最高総資産 ${yen(peak.total_jpy)} (${peak.date}) ・ ピーク比 ${pct(drawdown)} ・ ${rateNote}`,
  }],
});

blocks.push({ type: 'divider' });

if (useChartBlocks) {
  // グラフは data_visualization ブロックとしてスレッドに投稿する（後段の2ノードが担当）
  blocks.push({
    type: 'context',
    elements: [{ type: 'mrkdwn', text: '📈 グラフはこのメッセージのスレッドに投稿します' }],
  });
} else {
  // ---- フォールバック：テキストのグラフ ----
  const win = history.slice(-chartDays);
  const maxAbs = Math.max(1, ...win.map((r) => Math.abs(r.daily_pnl_jpy)));
  const BAR = 16;
  const chart = win.map((r) => {
    const len = Math.max(1, Math.round((Math.abs(r.daily_pnl_jpy) / maxAbs) * BAR));
    const bar = (r.daily_pnl_jpy >= 0 ? '█' : '░').repeat(len);
    const flag = r.effective_flow_jpy ? ' ⇄' : '';
    return `${r.date.slice(5)}  ${man(r.daily_pnl_jpy).padStart(10)}円  ${bar}${flag}`;
  }).join('\n');

  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*日次損益（直近${win.length}日）*\n\`\`\`\n${chart}\n\`\`\`` } });
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*総資産の推移*  \`${spark(history.slice(-30).map((r) => r.total_jpy))}\`\n`
        + `*累計損益の推移*  \`${spark(history.slice(-30).map((r) => r.cumulative_pnl_jpy))}\`\n_直近30日_`,
    },
  });
}

// 取得エラー・換算不能があれば警告（未開設ウォレットは毎日出るのでここには含めない）
const warns = [];
for (const e of (src.errors || [])) warns.push(`${e.kind} の取得に失敗 (${e.msg || e.status})`);
for (const w of (src.incomplete || [])) warns.push(w);
if ((src.unconverted || []).length) warns.push(`円換算できない入出金: ${src.unconverted.join(', ')}`);
for (const a of (src.anomalies || [])) warns.push(a);
for (const r of (src.review || []).slice(0, 5)) warns.push(`要確認: ${r}`);
if (warns.length) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `⚠️ *要確認*\n${warns.map((w) => `• ${w}`).join('\n')}` },
  });
}

return [{
  json: {
    channel,
    blocks,
    fallbackText: `Binance 現物レポート ${latest.date}: 前日比 ${signedYen(day1)} / 累計 ${signedYen(cumTotal)}`,
    summary: { date: latest.date, total_jpy: latest.total_jpy, day1, day7, day30, cumTotal, totalPct },
  },
}];

// ===== Slack APIは失敗してもHTTP 200 を返すので、ここで結果を確認する =====
const res = $input.first().json || {};
if (res.ok === false) {
  const e = res.error || '不明なエラー';
  const hint = {
    not_in_channel: '（Botをチャンネルに招待してください）',
    channel_not_found: '（設定ノードの slackChannel を確認してください）',
    invalid_auth: '（Slack認証情報を再接続してください）',
    missing_scope: `（Botに chat:write 権限が必要です。不足: ${res.needed || '不明'}）`,
    invalid_blocks: '（data_visualization ブロックが未対応の可能性があります。設定ノードの useChartBlocks を false にするとテキスト描画に切り替わります）',
    invalid_blocks_format: '（data_visualization ブロックが未対応の可能性があります。設定ノードの useChartBlocks を false にするとテキスト描画に切り替わります）',
  }[e] || '';
  throw new Error(`Slackへの送信に失敗しました: ${e}${hint}`);
}
return [{ json: { ok: true, channel: res.channel, ts: res.ts } }];

// ===== グラフをスレッドに投稿するためのメッセージ生成 =====
// data_visualization は 1メッセージにつき2ブロックまでなので、2個ずつに分割して複数itemを返す。
// 後段のHTTPノードがitemごとに chat.postMessage を実行する。
const cfg = $('設定').first().json;
const src = $('集計して推移を再計算').first().json;
const sent = $input.first().json || {};

const useChartBlocks = cfg.useChartBlocks !== false;
const history = src.history || [];
// 親メッセージの送信に失敗している / グラフ無効 / データ無しなら何も送らない
if (!useChartBlocks || !sent.ts || !sent.channel || !history.length) return [];

const chartDays = Math.min(20, Math.max(2, Number(cfg.chartDays) || 14));
const win = history.slice(-chartDays);
const categories = win.map((r) => r.date.slice(5));

// 値が大きいときは万円単位に落として軸を読みやすくする
const unitFor = (values) => {
  const max = Math.max(0, ...values.map((v) => Math.abs(v)));
  return max >= 1000000
    ? { div: 10000, label: '万円', digits: 1 }
    : { div: 1, label: '円', digits: 0 };
};
const scaled = (v, u) => Number((v / u.div).toFixed(u.digits));
const series = (name, key, u) => ([{
  name,
  data: win.map((r) => ({ label: r.date.slice(5), value: scaled(r[key], u) })),
}]);
const axis = (yLabel) => ({ categories, x_label: '日付 (UTC)', y_label: yLabel });

const charts = [];

// ① 総資産の推移
const uTotal = unitFor(win.map((r) => r.total_jpy));
charts.push({
  type: 'data_visualization',
  block_id: 'chart_total_assets',
  title: `総資産の推移（直近${win.length}日）`,
  chart: { type: 'line', series: series('総資産', 'total_jpy', uTotal), axis_config: axis(`総資産（${uTotal.label}）`) },
});

// ② 日次損益（入出金を除外した純損益）
const uPnl = unitFor(win.map((r) => r.daily_pnl_jpy));
charts.push({
  type: 'data_visualization',
  block_id: 'chart_daily_pnl',
  title: `日次損益（直近${win.length}日）`,
  chart: { type: 'bar', series: series('日次損益', 'daily_pnl_jpy', uPnl), axis_config: axis(`損益（${uPnl.label}）`) },
});

// ③ 累計損益の推移
const uCum = unitFor(win.map((r) => r.cumulative_pnl_jpy));
charts.push({
  type: 'data_visualization',
  block_id: 'chart_cumulative_pnl',
  title: `累計損益の推移（直近${win.length}日）`,
  chart: { type: 'area', series: series('累計損益', 'cumulative_pnl_jpy', uCum), axis_config: axis(`累計損益（${uCum.label}）`) },
});

// ④ 資産構成（最新スナップショットの現在評価額）
const comp = (src.composition || []).filter((c) => c && c.jpy > 0);
if (comp.length) {
  // 円グラフのセグメント上限は12。超える分は「その他」にまとめる
  const MAX = 12;
  let segments = comp.map((c) => ({ label: String(c.coin).slice(0, 20), value: c.jpy }));
  if (segments.length > MAX) {
    const head = segments.slice(0, MAX - 1);
    const rest = segments.slice(MAX - 1).reduce((a, s) => a + s.value, 0);
    segments = rest > 0 ? [...head, { label: 'その他', value: rest }] : head;
  }
  charts.push({
    type: 'data_visualization',
    block_id: 'chart_composition',
    title: `資産構成（${src.compositionDate || ''}）`.slice(0, 50),
    chart: { type: 'pie', segments },
  });
}

// 2個ずつに分割して1メッセージ = 最大2ブロックにする
const messages = [];
for (let i = 0; i < charts.length; i += 2) messages.push(charts.slice(i, i + 2));

return messages.map((blocks, i) => ({
  json: {
    channel: sent.channel,
    thread_ts: sent.ts,
    blocks,
    fallbackText: `グラフ (${i + 1}/${messages.length}): ${blocks.map((b) => b.title).join(' / ')}`,
  },
}));

// ===== スレッド投稿の結果を確認 =====
const bad = $input.all().map((i) => i.json).filter((r) => r && r.ok === false);
if (bad.length) {
  const e = bad[0].error || '不明なエラー';
  throw new Error(`スレッドへのグラフ投稿に失敗しました: ${e}`
    + (e === 'invalid_blocks' || e === 'invalid_blocks_format'
        ? '（data_visualization ブロックが未対応の可能性があります。設定ノードの useChartBlocks を false にするとテキスト描画に切り替わります）' : ''));
}
return [{ json: { ok: true, posted: $input.all().length } }];

// ===== Binance への署名付きリクエストをまとめて組み立てる =====
// 1つのCodeノードで複数リクエストを作り、後段のCrypto/HTTPノードが1件ずつ処理する
const cfg = $('設定').first().json;

// --- 認証情報の存在チェック（n8n 2.0 以降 $env は既定でブロックされる）
let apiKey = '';
let apiSecret = '';
try {
  apiKey = ($env && $env.BINANCE_API_KEY) || '';
  apiSecret = ($env && $env.BINANCE_API_SECRET) || '';
} catch (e) {
  apiKey = '';
  apiSecret = '';
}
if (!apiKey || !apiSecret) {
  throw new Error(
    '環境変数 BINANCE_API_KEY / BINANCE_API_SECRET を参照できません。'
    + 'n8n 2.0 以降は N8N_BLOCK_ENV_ACCESS_IN_NODE の既定が true（ブロック）です。'
    + 'セルフホストなら N8N_BLOCK_ENV_ACCESS_IN_NODE=false を設定してください。',
  );
}

const now = Date.now();
const DAY = 86400000;
// 日境界(UTC 00:00)に揃える。揃えないと「30日前の当日早朝」の入出金だけが
// 取りこぼされ、シートに記録済みの値がリセットされて累計損益がずれる
const todayUtc0 = Math.floor(now / DAY) * DAY;
const FLOW_DAYS = 30;
const flowStart = todayUtc0 - FLOW_DAYS * DAY;

// スナップショットの照会期間は「30日未満」という制約がある。
// endTime を昨日の終わりに固定すると、実行時刻に関係なく常に 29日 − 1ms で安全
const snapStart = todayUtc0 - 29 * DAY;
const snapEnd = todayUtc0 - 1;

const q = (o) => Object.entries(o)
  .filter(([, v]) => v !== undefined && v !== null && v !== '')
  .map(([k, v]) => `${k}=${encodeURIComponent(v)}`)
  .join('&');

// recvWindow は最大 60000。15リクエストを逐次実行するため、
// timestamp を組み立て時に1回だけ計算する構成では 5000 だと後半が -1021 で落ちる
const RECV = 60000;

const reqs = [];

// --- 日次資産スナップショット（weight: IP 2400 / limit最大30 / 照会期間は30日未満・直近1ヶ月のみ）
reqs.push({
  kind: 'snapshot',
  endpoint: '/sapi/v1/accountSnapshot',
  query: q({ type: 'SPOT', startTime: snapStart, endTime: snapEnd, limit: 30, recvWindow: RECV, timestamp: now }),
});

// --- 暗号資産の入出金（weight: 入金 IP 1 / 出金 UID 18000・毎秒10回まで。どちらも照会期間は90日未満）
reqs.push({
  kind: 'deposit',
  endpoint: '/sapi/v1/capital/deposit/hisrec',
  query: q({ startTime: flowStart, endTime: now, limit: 1000, recvWindow: RECV, timestamp: now }),
});
reqs.push({
  kind: 'withdraw',
  endpoint: '/sapi/v1/capital/withdraw/history',
  query: q({ startTime: flowStart, endTime: now, limit: 1000, recvWindow: RECV, timestamp: now }),
});

// --- 法定通貨(JPY)の入出金
// /sapi/v1/fiat/orders は重い。現行のAPIリファレンスは UID 45000、
// 変更履歴(2022-05-31)は UID 90000 と記載があり食い違っている。
// UID制限はエンドポイントごとに独立して毎分180000なので、入金・出金の2回で90000〜180000を消費する。
// 1日1回なら問題ないが、同じ1分内に手動で再実行すると 429 になりうる（後段で専用メッセージを出す）
if (cfg.trackFiat) {
  for (const t of ['0', '1']) {
    reqs.push({
      kind: t === '0' ? 'fiatDeposit' : 'fiatWithdraw',
      endpoint: '/sapi/v1/fiat/orders',
      query: q({ transactionType: t, beginTime: flowStart, endTime: now, rows: 500, recvWindow: RECV, timestamp: now }),
    });
  }
  // 法定通貨で直接売買した分（weight: IP 1 と軽い。paymentMethod は transactionType=0 のときだけ返る）
  for (const t of ['0', '1']) {
    reqs.push({
      kind: t === '0' ? 'fiatBuy' : 'fiatSell',
      endpoint: '/sapi/v1/fiat/payments',
      query: q({ transactionType: t, beginTime: flowStart, endTime: now, rows: 500, recvWindow: RECV, timestamp: now }),
    });
  }
}

// --- ウォレット間の振替（weight: IP 1 / size最大100 / 照会は直近6ヶ月まで）
if (cfg.trackTransfers) {
  const types = [
    'MAIN_FUNDING', 'FUNDING_MAIN',
    'MAIN_UMFUTURE', 'UMFUTURE_MAIN',
    'MAIN_CMFUTURE', 'CMFUTURE_MAIN',
    'MAIN_MARGIN', 'MARGIN_MAIN',
  ];
  for (const t of types) {
    reqs.push({
      kind: `transfer:${t}`,
      endpoint: '/sapi/v1/asset/transfer',
      query: q({ type: t, startTime: flowStart, endTime: now, size: 100, recvWindow: RECV, timestamp: now }),
    });
  }
}

return reqs.map((r) => ({ json: { baseUrl: 'https://api.binance.com', flowStart, ...r } }));

// ===== 複数レスポンスを種類別に仕分けし、入出金を正規化する =====
const cfg = $('設定').first().json;
const reqs = $('リクエストを組み立て').all().map((i) => i.json);
const items = $input.all();

const idxOf = (it, i) => {
  const p = it.pairedItem;
  if (typeof p === 'number') return p;
  if (p && typeof p.item === 'number') return p.item;
  if (Array.isArray(p) && p.length && typeof p[0].item === 'number') return p[0].item;
  return i;
};

// "2019-10-12 11:12:02" (UTC) / ミリ秒数値 のどちらにも対応
const toMs = (v) => {
  if (v === undefined || v === null || v === '') return 0;
  if (typeof v === 'number') return v;
  if (/^\d+$/.test(String(v))) return Number(v);
  const t = Date.parse(String(v).replace(' ', 'T') + 'Z');
  return Number.isFinite(t) ? t : 0;
};

let snapshots = [];
const flows = [];          // { time, coin, amount(符号付き), label }
const errors = [];         // Slackに警告として出す取得エラー
const review = [];         // 判断が必要なもの
const skippedWallets = []; // 未開設のウォレット（毎日出るノイズなので警告にしない）

// 認証・時刻ずれ・レート制限は種類を問わず必ず報告する
const ALWAYS_REPORT = new Set([-1021, -1022, -1002, -1003, -2014, -2015]);

items.forEach((it, i) => {
  const req = reqs[idxOf(it, i)] || reqs[i] || {};
  const kind = req.kind || 'unknown';
  const res = it.json || {};
  const body = res.body !== undefined ? res.body : res;
  const status = res.statusCode;
  const code = body && body.code !== undefined ? Number(body.code) : NaN;

  const isError = (status && status >= 400)
    || (body && body.code && body.code !== 200 && body.code !== '000000' && body.msg);

  if (isError) {
    // レート制限は原因が分かりにくいので専用メッセージにする
    if (status === 429 || code === -1003) {
      errors.push({
        kind,
        status: status || code,
        msg: 'Binanceのレート制限に達しました（/sapi/v1/fiat/orders は1回あたりUID weight 45000〜90000、'
          + 'このエンドポイント単独の上限は毎分180000です。同じ1分内に再実行しないでください）',
      });
      return;
    }
    // 未開設のマージン/先物ウォレットは毎回エラーになるため警告から除外する
    if (kind.startsWith('transfer:') && !ALWAYS_REPORT.has(code)) {
      skippedWallets.push(kind.slice('transfer:'.length));
      return;
    }
    errors.push({ kind, status: status || body.code, msg: (body && (body.msg || body.message)) || '' });
    return;
  }

  if (kind === 'snapshot') {
    snapshots = (body && body.snapshotVos) || [];
    return;
  }

  if (kind === 'deposit') {
    // status 0=処理中 1=成功 2=拒否 6=着金済(出金不可) 7=誤入金 8=ユーザー確認待ち
    for (const r of (Array.isArray(body) ? body : [])) {
      if (![1, 6].includes(Number(r.status))) continue;
      // travelRuleStatus 1 = トラベルルールの情報提出待ち。残高に反映されていない可能性がある
      if (Number(r.travelRuleStatus) === 1) {
        review.push(
          `${new Date(toMs(r.insertTime)).toISOString().slice(0, 10)} の ${r.coin} 入金 ${r.amount} は`
          + 'トラベルルールの情報提出待ちです。残高に反映されていない場合は入出金から除外してください',
        );
      }
      flows.push({ time: toMs(r.insertTime), coin: r.coin, amount: Number(r.amount), label: '入金' });
    }
    return;
  }

  if (kind === 'withdraw') {
    for (const r of (Array.isArray(body) ? body : [])) {
      // 0=メール送信 2=承認待ち 4=処理中 6=完了（いずれも残高は引かれている）
      if (![0, 2, 4, 6].includes(Number(r.status))) continue;
      flows.push({ time: toMs(r.applyTime || r.completeTime), coin: r.coin, amount: -Number(r.amount), label: '出金' });
    }
    return;
  }

  // 法定通貨の入出金。PayPayマネーからの入金はここに method="PayPay money" で出る（実機確認済み）
  //   例: indicatedAmount 15000 − totalFee 110 = amount 14890 がウォレットに入る
  if (kind === 'fiatDeposit' || kind === 'fiatWithdraw') {
    const isDeposit = kind === 'fiatDeposit';
    for (const r of ((body && body.data) || [])) {
      if (!['Successful', 'Finished'].includes(String(r.status))) continue;
      const net = Number(r.amount);                 // 入金: 実際にウォレットへ入る額
      const gross = Number(r.indicatedAmount);      // 出金: ウォレットから引かれる額（手数料込み）
      let amt;
      if (isDeposit) {
        // 既定は net。手数料を損失として記録したい場合は 設定 で gross に切り替える
        amt = (cfg.countDepositFeeAsLoss && Number.isFinite(gross)) ? gross : net;
      } else {
        amt = -(Number.isFinite(gross) ? gross : net);
      }
      flows.push({
        time: toMs(r.createTime),
        coin: r.fiatCurrency,
        amount: amt,
        label: `法定通貨${isDeposit ? '入金' : '出金'}${r.method ? `(${r.method})` : ''}`,
      });
    }
    return;
  }

  // 法定通貨での購入。PayPay運用では「入金→残高で購入」の2段階になり全件 Cash Balance になる（実機確認済み）
  // ＝ ここは通常すべて除外される。将来カード等の外部決済で直接買った場合の取りこぼし防止用に残してある
  if (kind === 'fiatBuy') {
    for (const r of ((body && body.data) || [])) {
      if (!['Completed', 'Successful', 'Finished'].includes(String(r.status))) continue;
      const method = String(r.paymentMethod || '');
      // "Cash Balance" はウォレット内の残高で買っているので資金の出入りではない
      if (/cash\s*balance/i.test(method)) continue;
      const jpy = Number(r.sourceAmount) - (Number(r.totalFee) || 0);
      flows.push({
        time: toMs(r.createTime),
        coin: r.fiatCurrency,
        amount: jpy,
        label: `法定通貨購入${method ? `(${method})` : ''}`,
      });
    }
    return;
  }

  if (kind === 'fiatSell') {
    for (const r of ((body && body.data) || [])) {
      if (!['Completed', 'Successful', 'Finished'].includes(String(r.status))) continue;
      const jpy = Number(r.obtainAmount) || Number(r.sourceAmount) || 0;
      review.push(`法定通貨売却 ${new Date(toMs(r.createTime)).toISOString().slice(0, 10)} ${jpy}${r.fiatCurrency || ''}`);
      if (!cfg.countFiatSell) continue;
      flows.push({
        time: toMs(r.createTime),
        coin: r.fiatCurrency,
        amount: -jpy,
        label: '法定通貨売却',
      });
    }
    return;
  }

  if (kind.startsWith('transfer:')) {
    const type = kind.slice('transfer:'.length);
    const sign = type.startsWith('MAIN_') ? -1 : 1;   // MAIN=現物ウォレット
    for (const r of ((body && body.rows) || [])) {
      if (String(r.status) !== 'CONFIRMED') continue;
      flows.push({
        time: toMs(r.timestamp),
        coin: r.asset,
        amount: sign * Number(r.amount),
        label: `ウォレット振替(${type})`,
      });
    }
  }
});

const clean = flows.filter((f) => f.time && f.coin && Number.isFinite(f.amount) && f.amount !== 0);

// --- 二重計上の検出 -------------------------------------------------
// 法定通貨がFundingに着金 → Spotへ振替、という経路だと
// 「法定通貨入金」と「FUNDING_MAIN振替」の両方が流入として加算されてしまう。
// 同じ日・同じ通貨・ほぼ同額の組み合わせが見つかったら要確認に出す。
const dayOf = (ms) => new Date(ms).toISOString().slice(0, 10);
for (const dep of clean) {
  if (!/^法定通貨入金/.test(dep.label) || dep.amount <= 0) continue;
  const hit = clean.find((t) => t.label === 'ウォレット振替(FUNDING_MAIN)'
    && t.coin === dep.coin
    && dayOf(t.time) === dayOf(dep.time)
    && Math.abs(t.amount - dep.amount) / Math.max(Math.abs(dep.amount), 1) <= 0.05);
  if (hit) {
    review.push(
      `${dayOf(dep.time)} の ${dep.coin} 入金が「法定通貨入金」と「FUNDING_MAIN振替」で二重計上されている可能性があります`
      + `（各 ${Math.round(dep.amount).toLocaleString('ja-JP')}）。実際の着金先ウォレットを確認してください`,
    );
  }
}

return [{
  json: {
    snapshots,
    flows: clean,
    errors,
    review,
    skippedWallets: [...new Set(skippedWallets)],
    flowStart: reqs.length ? reqs[0].flowStart : 0,
  },
}];

// ===== 履歴・スナップショット・入出金をマージして推移を再計算 =====
const cfg = $('設定').first().json;
const src = $('レスポンスを仕分け').first().json;

const DAY = 86400000;
const utcDate = (ms) => new Date(Number(ms)).toISOString().slice(0, 10);
const num = (v) => {
  const n = Number(String(v ?? '').replace(/[,¥\s]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const isBlank = (v) => v === undefined || v === null || String(v).trim() === '';

// 処理を中止して理由をSlackに出すための共通の戻り値
const abort = (reason) => ([{
  json: {
    fatal: reason,
    history: [], newRows: [], composition: [], compositionDate: null,
    rateSource: '', btcJpy: 0, latestDate: null,
    errors: src.errors || [], review: src.review || [],
    skippedWallets: src.skippedWallets || [],
    anomalies: [], incomplete: [], skippedDates: [], unconverted: [],
  },
}]);

// ---------- 1. 価格テーブル ----------
const px = {};
try {
  const body = $('価格一覧を取得').first().json.body || [];
  for (const p of body) px[p.symbol] = Number(p.price);
} catch (e) { /* noop */ }

// 為替レート（日次）: { "2026-09-18": { JPY: 152.34 }, ... } 営業日のみ
let fxByDate = {};
try {
  const fx = $('為替レート（日次）').first().json;
  fxByDate = (fx && fx.rates) || {};
} catch (e) { fxByDate = {}; }
const fxDates = Object.keys(fxByDate).sort();

// 為替APIが一時的に落ちてもレポートを止めないよう、最後に取れた値を保持しておく
const sd = (typeof $getWorkflowStaticData === 'function') ? $getWorkflowStaticData('global') : {};
const fxNotes = [];
let usdJpyFx = fxDates.length ? num(fxByDate[fxDates[fxDates.length - 1]].JPY) : 0;
if (usdJpyFx > 0) {
  sd.usdJpy = usdJpyFx;
  sd.usdJpyDate = fxDates[fxDates.length - 1];
} else if (num(sd.usdJpy) > 0) {
  usdJpyFx = num(sd.usdJpy);
  fxNotes.push(`為替レートを取得できなかったため前回値 ${usdJpyFx.toFixed(2)} (${sd.usdJpyDate || '日付不明'}) を使用しました`);
}

// 土日祝は前営業日のレートを使う
const usdJpyAt = (d) => {
  let v = 0;
  for (const k of fxDates) {
    if (k <= d) v = num(fxByDate[k].JPY); else break;
  }
  return v || usdJpyFx;
};

const usdtJpy = (px.BTCJPY && px.BTCUSDT) ? px.BTCJPY / px.BTCUSDT : (px.USDTJPY || usdJpyFx);
const btcJpyNow = px.BTCJPY || (px.BTCUSDT ? px.BTCUSDT * usdtJpy : 0);

// 円換算レートが取れないまま書き込むと総資産0円・巨額の偽損失がシートに残るため中止する
if (!(btcJpyNow > 0)) {
  return abort(
    'BTC/JPY の評価レートを取得できませんでした'
    + `（Binance価格一覧: ${px.BTCUSDT ? 'OK' : '失敗'} / 為替: ${usdJpyFx ? 'OK' : '失敗'}）。`
    + 'シートに誤った値を書き込まないよう、記録と集計を中止しました。',
  );
}

// ---------- 1-b. 日ごとのBTC/JPYレート ----------
// 初回のバックフィルで過去30日ぶんを「今日のレート」で評価すると、
// その期間の損益が数量変化しか反映しなくなるため、日足終値から日別レートを作る
const dailyBtcJpy = {};
try {
  const kl = $('日次BTC価格を取得').first().json.body || [];
  for (const k of kl) {
    if (!Array.isArray(k) || k.length < 5) continue;
    const d = utcDate(k[0]);                 // 日足のopenTime = その日の00:00 UTC
    const closeUsdt = Number(k[4]);          // 終値 = その日の23:59:59 UTC 時点
    const fx = usdJpyAt(d);
    if (closeUsdt > 0 && fx > 0) dailyBtcJpy[d] = closeUsdt * fx;
  }
} catch (e) { /* noop: btcJpyNow にフォールバック */ }
const rateAt = (d) => dailyBtcJpy[d] || btcJpyNow;

const rateSource = px.BTCJPY
  ? 'BTCJPY'
  : `BTCUSDT×USDJPY(${usdJpyFx.toFixed(2)})${Object.keys(dailyBtcJpy).length ? '・過去日は日足終値' : ''}`;

const STABLE = ['USDT', 'USDC', 'FDUSD', 'BUSD', 'DAI', 'TUSD'];
// その日のBTC/JPYレートを基準に、現在のコイン/BTC比率で換算する
const toJpy = (coin, amt, btcRate) => {
  const rate = btcRate || btcJpyNow;
  if (!amt || !coin) return 0;
  if (coin === 'JPY') return amt;
  if (coin === 'BTC') return amt * rate;
  if (px[`${coin}BTC`]) return amt * px[`${coin}BTC`] * rate;
  if (px[`${coin}USDT`] && px.BTCUSDT) return amt * (px[`${coin}USDT`] / px.BTCUSDT) * rate;
  if (STABLE.includes(coin) && px.BTCUSDT) return amt * (1 / px.BTCUSDT) * rate;
  if (px[`${coin}JPY`]) return amt * px[`${coin}JPY`];
  return NaN;   // 換算不能 → 後段で警告
};

// ---------- 2. 既存履歴（スプレッドシート） ----------
// シートの見出し（1行目）。ここを書き換えれば列名を変更できる
const COL = {
  date: '日付',
  total_btc: '総資産(BTC)',
  btc_price_jpy: 'BTC価格(円)',   // 書き込まない（旧シートに残っていれば読むだけ）
  total_jpy: '総資産(円)',
  net_flow_jpy: '入出金(円)',
  flow_note: '入出金メモ',
  daily_pnl_jpy: '日次損益(円)',
  daily_pnl_pct: '日次損益率(%)',
  cumulative_pnl_jpy: '累計損益(円)',
  net_flow_override_jpy: '入出金の手動補正(円)',
};
// 日本語見出しを優先しつつ、旧・英語見出しのシートもそのまま読めるようにする
const col = (r, key) => (r[COL[key]] !== undefined ? r[COL[key]] : r[key]);

// 日付セルがテキストでなく日付型になっていると "2026/09/19" 等で返り、
// キーが一致せず行が増殖する。読み取り側で正規化して吸収する
const SHEET_EPOCH = Date.UTC(1899, 11, 30);
const dateWarn = new Set();
const normDate = (v) => {
  if (v === undefined || v === null) return '';
  if (v instanceof Date) return v.toISOString().slice(0, 10);
  if (typeof v === 'number') {
    if (v > 20000 && v < 80000) { dateWarn.add('シリアル値'); return new Date(SHEET_EPOCH + Math.round(v) * DAY).toISOString().slice(0, 10); }
    if (v > 1e12) return new Date(v).toISOString().slice(0, 10);
    return '';
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
  if (m) { if (s[4] !== '-') dateWarn.add(s.slice(0, 10)); return `${m[1]}-${String(m[2]).padStart(2, '0')}-${String(m[3]).padStart(2, '0')}`; }
  m = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);
  if (m) { dateWarn.add(s.slice(0, 10)); return `${m[3]}-${String(m[1]).padStart(2, '0')}-${String(m[2]).padStart(2, '0')}`; }
  m = s.match(/^(\d{4})年(\d{1,2})月(\d{1,2})日/);
  if (m) { dateWarn.add(s.slice(0, 12)); return `${m[1]}-${String(m[2]).padStart(2, '0')}-${String(m[3]).padStart(2, '0')}`; }
  const t = Date.parse(s);
  if (Number.isFinite(t)) { dateWarn.add(s.slice(0, 12)); return new Date(t).toISOString().slice(0, 10); }
  return '';
};

const rawExisting = $('履歴を読み込み').all().map((i) => i.json);
// 読み込みに失敗したまま進むと、履歴が直近30日だけで再構築され
// 累計損益が0から振り直された値でシートを上書きしてしまう
const readErrRow = rawExisting.find((r) => r && r.error && isBlank(col(r, 'date')));
if (readErrRow) {
  const m = typeof readErrRow.error === 'string' ? readErrRow.error : (readErrRow.error.message || JSON.stringify(readErrRow.error));
  return abort(`スプレッドシートの読み込みに失敗しました（${m}）。累計損益が壊れるため、記録と集計を中止しました。`);
}

const existing = rawExisting.filter((r) => r && !isBlank(col(r, 'date')) && normDate(col(r, 'date')));

const map = new Map();
for (const r of existing) {
  const d = normDate(col(r, 'date'));
  const totalBtc = num(col(r, 'total_btc'));
  const totalJpy = num(col(r, 'total_jpy'));
  // BTC価格(円)はシートに書き込まないので 総資産(円) ÷ 総資産(BTC) で復元する
  const storedPrice = col(r, 'btc_price_jpy');
  map.set(d, {
    date: d,
    total_btc: totalBtc,
    btc_price_jpy: isBlank(storedPrice) ? (totalBtc ? totalJpy / totalBtc : 0) : num(storedPrice),
    total_jpy: totalJpy,
    net_flow_jpy: num(col(r, 'net_flow_jpy')),
    flow_note: col(r, 'flow_note') || '',
    // 自動検出を上書きしたいときだけ手入力する列（通常は空のまま）
    _override: isBlank(col(r, 'net_flow_override_jpy')) ? null : num(col(r, 'net_flow_override_jpy')),
  });
}

// ---------- 3-0. 不完全なスナップショットを検出 ----------
// Binanceが balances の一部を欠落させたまま totalAssetOfBtc を返すことがある。
// 前日にあった資産が丸ごと消え、かつそれを戻すと前日の総額が再現できる日は
// 「実際に減ったのではなく取得漏れ」と判断して集計から除外する。
const snapsSorted = (src.snapshots || [])
  .filter((s) => s && s.updateTime && s.data)
  .slice()
  .sort((a, b) => Number(a.updateTime) - Number(b.updateTime));

const balOf = (s) => {
  const m = new Map();
  for (const b of (s.data.balances || [])) {
    const amt = Number(b.free || 0) + Number(b.locked || 0);
    if (amt > 0) m.set(b.asset, amt);
  }
  return m;
};

// コイン数量 → BTC建て評価
const toBtc = (coin, amt) => {
  if (!amt || !coin) return NaN;
  if (coin === 'BTC') return amt;
  if (px[`${coin}BTC`]) return amt * px[`${coin}BTC`];
  if (px[`${coin}USDT`] && px.BTCUSDT) return amt * (px[`${coin}USDT`] / px.BTCUSDT);
  if (STABLE.includes(coin) && px.BTCUSDT) return amt / px.BTCUSDT;
  if (coin === 'JPY') return btcJpyNow ? amt / btcJpyNow : NaN;
  if (px[`${coin}JPY`] && btcJpyNow) return (amt * px[`${coin}JPY`]) / btcJpyNow;
  return NaN;
};

// その日に出金・振替が検出されたコイン（正当な減少かどうかの判定に使う）
const outflowOf = new Map();
for (const f of (src.flows || [])) {
  if (!(Number(f.amount) < 0)) continue;
  const d = utcDate(f.time);
  if (!outflowOf.has(d)) outflowOf.set(d, new Set());
  outflowOf.get(d).add(f.coin);
}

const badDates = new Map();   // date -> 欠損スナップショットが報告した totalAssetOfBtc
const incomplete = [];
for (let i = 1; i < snapsSorted.length; i++) {
  const p = snapsSorted[i - 1];
  const s = snapsSorted[i];
  const d = utcDate(s.updateTime);
  const pb = balOf(p);
  const sb = balOf(s);
  const missing = [...pb.keys()].filter((a) => !sb.has(a));
  if (!missing.length) continue;
  // 出金・振替が検出されていれば正当な減少
  const out = outflowOf.get(d) || new Set();
  if (missing.some((a) => out.has(a))) continue;

  const pTot = Number(p.data.totalAssetOfBtc);
  const sTot = Number(s.data.totalAssetOfBtc);
  if (!(pTot > 0) || !Number.isFinite(sTot) || sTot >= pTot) continue;

  let missBtc = 0;
  let evaluable = true;
  for (const a of missing) {
    const v = toBtc(a, pb.get(a));
    if (!Number.isFinite(v)) { evaluable = false; break; }
    missBtc += v;
  }
  if (!evaluable) continue;

  // 消えた資産を戻すと前日の総額とほぼ一致する = 資産は動いていない
  // （売却・両替なら総額は保たれるのでここには該当しない）
  if (Math.abs((sTot + missBtc) - pTot) / pTot <= 0.10) {
    badDates.set(d, sTot);
    incomplete.push(`${d} のスナップショットが不完全なため集計から除外しました（${missing.join(', ')} が欠落。Binance側の取得漏れ）`);
  }
}

// 既にシートへ書き込まれた欠損値の行も集計から外す（値が一致する場合のみ）
for (const [d, badTot] of badDates) {
  const row = map.get(d);
  if (!row) continue;
  const ref = Math.max(Math.abs(badTot), 1e-12);
  if (Math.abs(row.total_btc - badTot) / ref <= 0.02) {
    map.delete(d);
    incomplete.push(`${d} の記録済みの行は欠損値のため無効化しました（シートの該当行は手動で削除してください）`);
  }
}

// ---------- 3-1. 最新の資産構成（円グラフ用） ----------
const lastGood = [...snapsSorted].reverse().find((s) => !badDates.has(utcDate(s.updateTime)));
const composition = [];
let compositionDate = null;
if (lastGood) {
  compositionDate = utcDate(lastGood.updateTime);
  for (const [coin, amt] of balOf(lastGood)) {
    const b = toBtc(coin, amt);
    const jpy = Number.isFinite(b) ? b * btcJpyNow : NaN;
    if (Number.isFinite(jpy) && jpy > 0) composition.push({ coin, amount: amt, jpy: Math.round(jpy) });
  }
  composition.sort((a, b) => b.jpy - a.jpy);
}

// ---------- 3. スナップショットを反映 ----------
const freshDates = [];
for (const s of (src.snapshots || [])) {
  if (!s || !s.updateTime || !s.data) continue;
  const d = utcDate(s.updateTime);
  if (badDates.has(d)) continue;
  const btc = num(s.data.totalAssetOfBtc);
  const prev = map.get(d) || {};
  // 一度記録した日の評価レートは維持する。未記録の日はその日の日足レートを使う
  const price = prev.btc_price_jpy || rateAt(d);
  map.set(d, {
    ...prev,
    date: d,
    total_btc: btc,
    btc_price_jpy: price,
    total_jpy: btc * price,
    net_flow_jpy: prev.net_flow_jpy || 0,
    flow_note: prev.flow_note || '',
    _override: prev._override ?? null,
  });
  freshDates.push(d);
}

// ---------- 4. 入出金を日別に集計（取得できた期間のみ再計算） ----------
const flowFrom = src.flowStart ? utcDate(src.flowStart) : null;
const unconverted = [];
if (flowFrom) {
  for (const [d, row] of map) {
    if (d >= flowFrom) { row.net_flow_jpy = 0; row.flow_note = ''; }
  }
  const bucket = new Map();
  for (const f of (src.flows || [])) {
    const d = utcDate(f.time);
    if (d < flowFrom) continue;
    if (!bucket.has(d)) bucket.set(d, { jpy: 0, notes: new Map() });
    const b = bucket.get(d);
    const row = map.get(d);
    const jpy = toJpy(f.coin, f.amount, row ? row.btc_price_jpy : rateAt(d));
    if (!Number.isFinite(jpy)) { unconverted.push(`${d} ${f.coin}`); continue; }
    b.jpy += jpy;
    const short = f.label.replace(/^ウォレット振替\(.+\)$/, 'ウォレット振替');
    b.notes.set(short, (b.notes.get(short) || 0) + 1);
  }
  for (const [d, b] of bucket) {
    const row = map.get(d);
    if (!row) continue;
    row.net_flow_jpy = Math.round(b.jpy);
    row.flow_note = [...b.notes.entries()].map(([k, v]) => `${k}${v}件`).join(' / ');
  }
}

// ---------- 5. 日次損益・累計を再計算 ----------
const history = [...map.values()].sort((a, b) => (a.date < b.date ? -1 : 1));
let cum = 0;
for (let i = 0; i < history.length; i++) {
  const r = history[i];
  const p = history[i - 1];
  const flow = r._override !== null && r._override !== undefined ? r._override : r.net_flow_jpy;
  // 収益 = 総資産の増減 − 入出金
  const diff = p ? r.total_jpy - p.total_jpy - flow : 0;
  const base = p ? p.total_jpy + flow : 0;
  cum += diff;
  r.effective_flow_jpy = Math.round(flow);
  r.total_btc = Number(r.total_btc.toFixed(8));
  r.btc_price_jpy = Math.round(r.btc_price_jpy);
  r.total_jpy = Math.round(r.total_jpy);
  r.net_flow_jpy = Math.round(r.net_flow_jpy);
  r.daily_pnl_jpy = Math.round(diff);
  r.daily_pnl_pct = base ? Number(((diff / base) * 100).toFixed(3)) : 0;
  r.cumulative_pnl_jpy = Math.round(cum);
}

// ---------- 6. 書き込み対象（手入力列は書き戻さない） ----------
const from = freshDates.length ? freshDates.slice().sort()[0] : null;
const writable = (r) => ({
  [COL.date]: r.date,
  [COL.total_btc]: r.total_btc,
  [COL.total_jpy]: r.total_jpy,
  [COL.net_flow_jpy]: r.net_flow_jpy,
  [COL.flow_note]: r.flow_note,
  [COL.daily_pnl_jpy]: r.daily_pnl_jpy,
  [COL.daily_pnl_pct]: r.daily_pnl_pct,
  [COL.cumulative_pnl_jpy]: r.cumulative_pnl_jpy,
});
const newRows = from ? history.filter((r) => r.date >= from).map(writable) : [];

// ---------- 7. 入出金の取りこぼし検知 ----------
// 入出金が検出されていないのに総資産が大きく動いた日を洗い出す。
// 暗号資産は15%程度なら普通に動くので、率と実額の両方をしきい値にする
const anomalyPct = Number(cfg.anomalyPct) || 20;
const anomalyMinJpy = Number(cfg.anomalyMinJpy) || 0;
const anomalies = [];
for (let i = 1; i < history.length; i++) {
  const r = history[i];
  const p = history[i - 1];
  if (flowFrom && r.date < flowFrom) continue;
  if (r.effective_flow_jpy) continue;
  if (!p.total_jpy) continue;
  if (Math.abs(r.daily_pnl_jpy) < anomalyMinJpy) continue;
  if (Math.abs(r.daily_pnl_jpy / p.total_jpy) * 100 >= anomalyPct) {
    anomalies.push(`${r.date} の変動 ${r.daily_pnl_jpy >= 0 ? '+' : ''}${r.daily_pnl_jpy.toLocaleString('ja-JP')}円 (${r.daily_pnl_pct}%) に対応する入出金が未検出`);
  }
}

const review = [...(src.review || []), ...fxNotes];
if (dateWarn.size) {
  review.push(`シートの「${COL.date}」列が日付型として読まれています（例: ${[...dateWarn][0]}）。書式を「書式なしテキスト」にすると行の重複を防げます`);
}

return [{
  json: {
    fatal: null,
    history,
    newRows,
    rateSource,
    btcJpy: Math.round(btcJpyNow),
    errors: src.errors || [],
    review,
    skippedWallets: src.skippedWallets || [],
    anomalies,
    incomplete,
    skippedDates: [...badDates.keys()],
    composition,
    compositionDate,
    unconverted: [...new Set(unconverted)],
    latestDate: history.length ? history[history.length - 1].date : null,
  },
}];

// ===== Slack Block Kit メッセージ生成（JPY建て） =====
const cfg = $('設定').first().json;
const src = $input.first().json;

// 投稿先チャンネル（設定ノードで管理し、送信ノードには $json.channel として渡す）
const channel = String(cfg.slackChannel || '').trim();
if (!channel) {
  throw new Error('設定ノードの slackChannel が空です。投稿先チャンネルのID（C から始まる文字列）を指定してください。');
}
const history = src.history || [];

// data_visualization ブロックを使うか（false ならテキストのグラフにフォールバック）
const useChartBlocks = cfg.useChartBlocks !== false;
// グラフに載せる日数（data_visualization の上限は 20 点）
const chartDays = Math.min(20, Math.max(2, Number(cfg.chartDays) || 14));

const yen = (n) => `${Math.round(Math.abs(n)).toLocaleString('ja-JP')} 円`;
const signedYen = (n) => `${n >= 0 ? '+' : '-'}${yen(n)}`;
const man = (n) => {
  const v = Math.abs(n) / 10000;
  return `${n >= 0 ? '+' : '-'}${v.toLocaleString('ja-JP', { minimumFractionDigits: 1, maximumFractionDigits: 1 })}万`;
};
const pct = (n) => `${n >= 0 ? '+' : '-'}${Math.abs(n).toFixed(2)}%`;
const emo = (n) => (n > 0 ? '🟢' : n < 0 ? '🔴' : '⚪️');

const spark = (arr) => {
  if (!arr.length) return '';
  const chars = '▁▂▃▄▅▆▇█';
  const mn = Math.min(...arr);
  const mx = Math.max(...arr);
  const rng = (mx - mn) || 1;
  return arr.map((v) => chars[Math.min(7, Math.floor(((v - mn) / rng) * 7.999))]).join('');
};

// ---- 中止された場合（レート取得失敗・シート読み込み失敗など）
if (src.fatal) {
  const detail = (src.errors || []).map((e) => `${e.kind}: ${e.msg || e.status}`).slice(0, 5);
  return [{
    json: {
      channel,
      blocks: [
        { type: 'section', text: { type: 'mrkdwn', text: `🛑 *Binance 収益レポートを中止しました*\n${src.fatal}` } },
        ...(detail.length ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: detail.map((d) => `• ${d}`).join('\n') }] }] : []),
        { type: 'context', elements: [{ type: 'mrkdwn', text: 'シートへの書き込みは行っていません。次回の実行で自動的に復旧します。' }] },
      ],
      fallbackText: `Binance 収益レポート: 中止（${src.fatal}）`,
    },
  }];
}

const latest = history[history.length - 1];
if (!latest) {
  const why = (src.errors || []).map((e) => `${e.kind}: ${e.msg || e.status}`).join(' / ') || 'レスポンスが空でした';
  return [{
    json: {
      channel,
      blocks: [{ type: 'section', text: { type: 'mrkdwn', text: `⚠️ Binance のスナップショットを取得できませんでした。\n\`${why}\`` } }],
      fallbackText: 'Binance 収益レポート: データ取得に失敗しました',
    },
  }];
}

const sumLast = (n) => history.slice(-n).reduce((a, b) => a + b.daily_pnl_jpy, 0);
const n7 = Math.min(7, history.length);
const n30 = Math.min(30, history.length);
const day1 = latest.daily_pnl_jpy;
const day7 = sumLast(n7);
const day30 = sumLast(n30);
const cumTotal = latest.cumulative_pnl_jpy;
const firstDate = history[0].date;

const principal = history[0].total_jpy + history.slice(1).reduce((a, b) => a + (b.effective_flow_jpy || 0), 0);
const totalPct = principal ? (cumTotal / principal) * 100 : 0;

const peak = history.reduce((m, r) => (r.total_jpy > m.total_jpy ? r : m), history[0]);
const drawdown = peak.total_jpy ? ((latest.total_jpy - peak.total_jpy) / peak.total_jpy) * 100 : 0;

const nowRate = src.btcJpy || latest.btc_price_jpy;
const rateNote = nowRate === latest.btc_price_jpy
  ? `評価レート 1BTC = ${yen(latest.btc_price_jpy)} (${src.rateSource})`
  : `${latest.date}の評価レート 1BTC = ${yen(latest.btc_price_jpy)} ・ 現在 ${yen(nowRate)} (${src.rateSource})`;

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: '📊 Binance 現物 収益レポート', emoji: true } },
  {
    type: 'context',
    elements: [{ type: 'mrkdwn', text: `対象日 *${latest.date}* (UTC基準) ・ 記録 ${history.length}日分 ・ ${firstDate} 〜` }],
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*総資産*\n*${yen(latest.total_jpy)}*  ( ${latest.total_btc.toFixed(8)} BTC )\n`
        + `前日比 ${emo(day1)} ${signedYen(day1)} ( ${pct(latest.daily_pnl_pct)} )`,
    },
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*直近${n7}日*\n${emo(day7)} ${signedYen(day7)}` },
      { type: 'mrkdwn', text: `*直近${n30}日*\n${emo(day30)} ${signedYen(day30)}` },
      { type: 'mrkdwn', text: `*累計損益*\n${emo(cumTotal)} ${signedYen(cumTotal)}` },
      { type: 'mrkdwn', text: `*累計リターン*\n${emo(totalPct)} ${pct(totalPct)}` },
    ],
  },
];

// 入出金が検出された日は明示する（収益から除外済み）
const flowDays = history.slice(-7).filter((r) => r.effective_flow_jpy);
if (flowDays.length) {
  blocks.push({
    type: 'context',
    elements: [{
      type: 'mrkdwn',
      text: `⇄ 直近7日の入出金（収益から除外済み）: `
        + flowDays.map((r) => `${r.date.slice(5)} ${signedYen(r.effective_flow_jpy)}${r.flow_note ? `（${r.flow_note}）` : ''}`).join(' ・ '),
    }],
  });
}

blocks.push({
  type: 'context',
  elements: [{
    type: 'mrkdwn',
    text: `最高総資産 ${yen(peak.total_jpy)} (${peak.date}) ・ ピーク比 ${pct(drawdown)} ・ ${rateNote}`,
  }],
});

blocks.push({ type: 'divider' });

if (useChartBlocks) {
  // グラフは data_visualization ブロックとしてスレッドに投稿する（後段の2ノードが担当）
  blocks.push({
    type: 'context',
    elements: [{ type: 'mrkdwn', text: '📈 グラフはこのメッセージのスレッドに投稿します' }],
  });
} else {
  // ---- フォールバック：テキストのグラフ ----
  const win = history.slice(-chartDays);
  const maxAbs = Math.max(1, ...win.map((r) => Math.abs(r.daily_pnl_jpy)));
  const BAR = 16;
  const chart = win.map((r) => {
    const len = Math.max(1, Math.round((Math.abs(r.daily_pnl_jpy) / maxAbs) * BAR));
    const bar = (r.daily_pnl_jpy >= 0 ? '█' : '░').repeat(len);
    const flag = r.effective_flow_jpy ? ' ⇄' : '';
    return `${r.date.slice(5)}  ${man(r.daily_pnl_jpy).padStart(10)}円  ${bar}${flag}`;
  }).join('\n');

  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*日次損益（直近${win.length}日）*\n\`\`\`\n${chart}\n\`\`\`` } });
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*総資産の推移*  \`${spark(history.slice(-30).map((r) => r.total_jpy))}\`\n`
        + `*累計損益の推移*  \`${spark(history.slice(-30).map((r) => r.cumulative_pnl_jpy))}\`\n_直近30日_`,
    },
  });
}

// 取得エラー・換算不能があれば警告（未開設ウォレットは毎日出るのでここには含めない）
const warns = [];
for (const e of (src.errors || [])) warns.push(`${e.kind} の取得に失敗 (${e.msg || e.status})`);
for (const w of (src.incomplete || [])) warns.push(w);
if ((src.unconverted || []).length) warns.push(`円換算できない入出金: ${src.unconverted.join(', ')}`);
for (const a of (src.anomalies || [])) warns.push(a);
for (const r of (src.review || []).slice(0, 5)) warns.push(`要確認: ${r}`);
if (warns.length) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `⚠️ *要確認*\n${warns.map((w) => `• ${w}`).join('\n')}` },
  });
}

return [{
  json: {
    channel,
    blocks,
    fallbackText: `Binance 現物レポート ${latest.date}: 前日比 ${signedYen(day1)} / 累計 ${signedYen(cumTotal)}`,
    summary: { date: latest.date, total_jpy: latest.total_jpy, day1, day7, day30, cumTotal, totalPct },
  },
}];

// ===== Slack APIは失敗してもHTTP 200 を返すので、ここで結果を確認する =====
const res = $input.first().json || {};
if (res.ok === false) {
  const e = res.error || '不明なエラー';
  const hint = {
    not_in_channel: '（Botをチャンネルに招待してください）',
    channel_not_found: '（設定ノードの slackChannel を確認してください）',
    invalid_auth: '（Slack認証情報を再接続してください）',
    missing_scope: `（Botに chat:write 権限が必要です。不足: ${res.needed || '不明'}）`,
    invalid_blocks: '（data_visualization ブロックが未対応の可能性があります。設定ノードの useChartBlocks を false にするとテキスト描画に切り替わります）',
    invalid_blocks_format: '（data_visualization ブロックが未対応の可能性があります。設定ノードの useChartBlocks を false にするとテキスト描画に切り替わります）',
  }[e] || '';
  throw new Error(`Slackへの送信に失敗しました: ${e}${hint}`);
}
return [{ json: { ok: true, channel: res.channel, ts: res.ts } }];

// ===== グラフをスレッドに投稿するためのメッセージ生成 =====
// data_visualization は 1メッセージにつき2ブロックまでなので、2個ずつに分割して複数itemを返す。
// 後段のHTTPノードがitemごとに chat.postMessage を実行する。
const cfg = $('設定').first().json;
const src = $('集計して推移を再計算').first().json;
const sent = $input.first().json || {};

const useChartBlocks = cfg.useChartBlocks !== false;
const history = src.history || [];
// 親メッセージの送信に失敗している / グラフ無効 / データ無しなら何も送らない
if (!useChartBlocks || !sent.ts || !sent.channel || !history.length) return [];

const chartDays = Math.min(20, Math.max(2, Number(cfg.chartDays) || 14));
const win = history.slice(-chartDays);
const categories = win.map((r) => r.date.slice(5));

// 値が大きいときは万円単位に落として軸を読みやすくする
const unitFor = (values) => {
  const max = Math.max(0, ...values.map((v) => Math.abs(v)));
  return max >= 1000000
    ? { div: 10000, label: '万円', digits: 1 }
    : { div: 1, label: '円', digits: 0 };
};
const scaled = (v, u) => Number((v / u.div).toFixed(u.digits));
const series = (name, key, u) => ([{
  name,
  data: win.map((r) => ({ label: r.date.slice(5), value: scaled(r[key], u) })),
}]);
const axis = (yLabel) => ({ categories, x_label: '日付 (UTC)', y_label: yLabel });

const charts = [];

// ① 総資産の推移
const uTotal = unitFor(win.map((r) => r.total_jpy));
charts.push({
  type: 'data_visualization',
  block_id: 'chart_total_assets',
  title: `総資産の推移（直近${win.length}日）`,
  chart: { type: 'line', series: series('総資産', 'total_jpy', uTotal), axis_config: axis(`総資産（${uTotal.label}）`) },
});

// ② 日次損益（入出金を除外した純損益）
const uPnl = unitFor(win.map((r) => r.daily_pnl_jpy));
charts.push({
  type: 'data_visualization',
  block_id: 'chart_daily_pnl',
  title: `日次損益（直近${win.length}日）`,
  chart: { type: 'bar', series: series('日次損益', 'daily_pnl_jpy', uPnl), axis_config: axis(`損益（${uPnl.label}）`) },
});

// ③ 累計損益の推移
const uCum = unitFor(win.map((r) => r.cumulative_pnl_jpy));
charts.push({
  type: 'data_visualization',
  block_id: 'chart_cumulative_pnl',
  title: `累計損益の推移（直近${win.length}日）`,
  chart: { type: 'area', series: series('累計損益', 'cumulative_pnl_jpy', uCum), axis_config: axis(`累計損益（${uCum.label}）`) },
});

// ④ 資産構成（最新スナップショットの現在評価額）
const comp = (src.composition || []).filter((c) => c && c.jpy > 0);
if (comp.length) {
  // 円グラフのセグメント上限は12。超える分は「その他」にまとめる
  const MAX = 12;
  let segments = comp.map((c) => ({ label: String(c.coin).slice(0, 20), value: c.jpy }));
  if (segments.length > MAX) {
    const head = segments.slice(0, MAX - 1);
    const rest = segments.slice(MAX - 1).reduce((a, s) => a + s.value, 0);
    segments = rest > 0 ? [...head, { label: 'その他', value: rest }] : head;
  }
  charts.push({
    type: 'data_visualization',
    block_id: 'chart_composition',
    title: `資産構成（${src.compositionDate || ''}）`.slice(0, 50),
    chart: { type: 'pie', segments },
  });
}

// 2個ずつに分割して1メッセージ = 最大2ブロックにする
const messages = [];
for (let i = 0; i < charts.length; i += 2) messages.push(charts.slice(i, i + 2));

return messages.map((blocks, i) => ({
  json: {
    channel: sent.channel,
    thread_ts: sent.ts,
    blocks,
    fallbackText: `グラフ (${i + 1}/${messages.length}): ${blocks.map((b) => b.title).join(' / ')}`,
  },
}));

// ===== スレッド投稿の結果を確認 =====
const bad = $input.all().map((i) => i.json).filter((r) => r && r.ok === false);
if (bad.length) {
  const e = bad[0].error || '不明なエラー';
  throw new Error(`スレッドへのグラフ投稿に失敗しました: ${e}`
    + (e === 'invalid_blocks' || e === 'invalid_blocks_format'
        ? '（data_visualization ブロックが未対応の可能性があります。設定ノードの useChartBlocks を false にするとテキスト描画に切り替わります）' : ''));
}
return [{ json: { ok: true, posted: $input.all().length } }];
